import './App.css';
import { useState } from 'react';
import Dashboard from './dashboard';
import Login from './login';
import Register from './register';

function App() {
  const [showRegister, setShowRegister] = useState(false);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [userName, setUserName] = useState('there');

  function handleLogin(name = 'there', role = 'User') {
    setUserName(name);
    setUserRole(role);
    setIsLoggedIn(true);
  }

  if (isLoggedIn) {
    return <Dashboard userName={userName} onLogout={() => setIsLoggedIn(false)} />;
  }

  return (
    showRegister
      ? <Register onLogin={() => setShowRegister(false)} onSuccess={handleLogin} />
      : <Login onRegister={() => setShowRegister(true)} onSuccess={handleLogin} />
  );
}

export default App;
